import { describe, it, expect } from 'vitest';
import { call, TOKENS } from './helpers';
import { POST } from '@/app/api/patients/search/route';

describe('patient search', () => {
  it('rejects non-practitioners', async () => {
    expect((await call(POST, { method: 'POST', token: TOKENS.ava, body: { q: 'av' } })).status).toBe(403);
    expect((await call(POST, { method: 'POST', token: TOKENS.dana, body: { q: 'av' } })).status).toBe(403);
  });
  it('validates q', async () => {
    expect((await call(POST, { method: 'POST', token: TOKENS.rosa, body: { q: 'a' } })).status).toBe(400);
  });
  it('searches own practice only, case-insensitively', async () => {
    const r = await call(POST, { method: 'POST', token: TOKENS.rosa, body: { q: 'A' + 'v' } });
    expect(r.status).toBe(200);
    expect(r.json.results.length).toBeGreaterThan(0);
    const h = await call(POST, { method: 'POST', token: TOKENS.hal, body: { q: 'av' } });
    const ids = new Set(h.json.results.map((p: any) => p.id));
    for (const p of r.json.results) expect(ids.has(p.id)).toBe(false);
  });
  it('treats wildcards literally', async () => {
    const r = await call(POST, { method: 'POST', token: TOKENS.rosa, body: { q: '%%' } });
    expect(r.json.results).toEqual([]);
  });
});
